async function marketDetail(env,symbol){if(!/^[\p{L}\p{N}_]{1,40}$/u.test(symbol))throw Error('币种参数无效');return cached(env,'market-detail-'+encodeURIComponent(symbol)+'.json',30000,async()=>{const [ticker,oi]=await Promise.allSettled([remote(HOST+'ticker/24hr?'+new URLSearchParams({symbol})),remote(HOST+'openInterest?'+new URLSearchParams({symbol}))]);const t=ticker.status==='fulfilled'?ticker.value:null,o=oi.status==='fulfilled'?oi.value:null;const valid=v=>v!=null&&v!==''&&Number.isFinite(Number(v));return {symbol,price:valid(t?.lastPrice)?t.lastPrice:null,change24:Number(t?.openPrice)>0&&Number(t?.lastPrice)>0?(Number(t.lastPrice)/Number(t.openPrice)-1)*100:null,quoteVolume:valid(t?.quoteVolume)?t.quoteVolume:null,baseVolume:valid(t?.volume)?t.volume:null,highPrice:valid(t?.highPrice)?t.highPrice:null,lowPrice:valid(t?.lowPrice)?t.lowPrice:null,tickerTime:t?.closeTime??null,openInterest:valid(o?.openInterest)&&Number(o.openInterest)>=0?o.openInterest:null,interestTime:o?.time??null,tickerError:t?null:(ticker.reason?.message||'行情暂不可用'),interestError:valid(o?.openInterest)?null:(oi.reason?.message||'未平仓量暂不可用'),source:HOST}})}

// 社区热度：X API v2 搜索最近推文（GET /2/tweets/search/recent，只返回最近 7 天）。
// 密钥只从 env.X_BEARER_TOKEN 读（server.js 从环境变量 X_BEARER_TOKEN 传入，
// 绝不写进代码、仓库或日志）；没配密钥时不调上游、不写缓存，直接返回 available:false。
// TTL 1800s：限额口径见 README.md / VERIFICATION.md（各公开来源对 recent search 的
// 15 分钟限额与月度上限说法不一，且“按请求计还是按返回推文条数计”也不一致；
// 1800s 即每小时最多 2 次上游请求、每天最多 48 次、每月最多约 1,440 次，
// 每次最多返回 10 条，即每月最多约 14,400 条，留足余量）。失败时沿用 cached() 的 stale 回退：有旧缓存返回
// 旧数据并标 stale:true，无旧缓存才抛错（路由层返回 502，前端显示“暂未接入”）。
// env.X_API_BASE 仅供本地联调覆盖上游地址（例如指到不可达地址测 stale 回退；
// 默认 https://api.x.com），生产不配。
async function community(env){
if(!env.X_BEARER_TOKEN)return {available:false,tweets:[],source:'X API v2 · GET /2/tweets/search/recent',note:'未配置 X_BEARER_TOKEN，暂不展示热度排行',updatedAt:Date.now()};
return cached(env,'community.json',1800000,async()=>{
const base=(env.X_API_BASE||'https://api.x.com').replace(/\/+$/,'');
const url=base+'/2/tweets/search/recent?'+new URLSearchParams({query:'$ASTER -is:retweet',max_results:'10','tweet.fields':'created_at,author_id,public_metrics',expansions:'author_id','user.fields':'username,name'});
let r=await fetch(url,{signal:AbortSignal.timeout(20000),headers:{Authorization:'Bearer '+env.X_BEARER_TOKEN,Accept:'application/json'}});
if(!r.ok)throw Error('X API HTTP '+r.status+(r.status===429?'（限流，稍后重试）':(r.status===401||r.status===403)?'（鉴权失败，请检查 X_BEARER_TOKEN 与套餐权限）':''));
let d=await r.json();
if(d.errors?.length)throw Error(d.errors[0]?.message||'X API 返回错误');
if(d.data&&!Array.isArray(d.data))throw Error('X API 返回格式异常');
const mapTweets=dd=>{const uu=Object.fromEntries((dd.includes?.users||[]).map(u=>[u.id,u]));return (dd.data||[]).map(t=>{const u=uu[t.author_id]||{};return {id:t.id,text:t.text,createdAt:t.created_at,author:{username:u.username||'',name:u.name||''},url:u.username?('https://x.com/'+u.username+'/status/'+t.id):('https://x.com/i/status/'+t.id),likes:t.public_metrics?.like_count??null,retweets:t.public_metrics?.retweet_count??null,replies:t.public_metrics?.reply_count??null,heat:(t.public_metrics?.like_count??0)+(t.public_metrics?.retweet_count??0)+(t.public_metrics?.reply_count??0)}})};
const tweets=mapTweets(d);
let officialAdded=0;
if(tweets.length<3){try{const ourl=base+'/2/tweets/search/recent?'+new URLSearchParams({query:'from:Aster_DEX -is:retweet',max_results:'5','tweet.fields':'created_at,author_id,public_metrics',expansions:'author_id','user.fields':'username,name'});let orr=await fetch(ourl,{signal:AbortSignal.timeout(20000),headers:{Authorization:'Bearer '+env.X_BEARER_TOKEN,Accept:'application/json'}});if(orr.ok){let od=await orr.json();const seen=new Set(tweets.map(x=>x.id));for(const ot of mapTweets(od)){if(!seen.has(ot.id)&&officialAdded<3){ot.official=true;tweets.push(ot);officialAdded++}}}}catch{}}
tweets.sort((a,b)=>(b.heat-a.heat)||(new Date(b.createdAt)-new Date(a.createdAt)));
return {available:true,tweets,query:'$ASTER -is:retweet',windowDays:7,source:'X API v2 · GET /2/tweets/search/recent',officialAdded};
});
}
// ===== BEGIN DAILY BRIEF =====
// 每日异动：GET /api/daily-brief。聚合 markets（复用其缓存与 stale 回退）+
// 前 3 名各追加查日内高低点与持仓量（marketDetail，复用其 30s 缓存）+
// 资金费率（Aster 公开接口 premiumIndex；失败只留空，不让整份异动失败）。
// TTL 300s，stale 回退走 cached()。
// 异动分（0-100）只用现有数据算，不编造 1h 数据：
//   涨幅分（50）= min(50, change24 * 0.125)
//   成交额分（20）= min(20, 4 * log10(quoteVolume / 10000))
//   资金费率分（15）= min(15, |fundingRate - 0.0001| * 1000)
//   领先分（15）= min(15, (change1 - change2) * 0.05)
// 开单思路（规则版，非投资建议）：只用现有信号判断，不接 LLM，见 briefIdea()。
// 关闭：server.js 传 env.DAILY_BRIEF_ENABLED=false（默认 true），
// 此时接口返回 404，前端区块保持隐藏。彻底删除见 README“每日异动”一节。
const BRIEF_DINO=['XLM','XTZ','LTC','ZEC'];
// 催化剂日历：人工维护的静态事件；date 过了当天（北京时间）自动隐藏。
// 有新事件往数组里加一行；删掉数组即去掉整个日历。
// 注意：这里只放妖币本身的事件，不放 ASTER 回购/销毁（回购卡片在首页别处）。
const BRIEF_EVENTS=[
{date:'2026-11-10',zh:{title:'JCT 上币币安 Alpha + 合约',note:'同日约 11.8 亿枚解锁（约占流通 10%）'},en:{title:'JCT lists on Binance Alpha + futures',note:'~1.18B unlock the same day (~10% of circulating supply)'}},
];
// 4 位有效数字取整（点位显示用）：0.01309 → 0.01309；51.75 → 51.75。
function briefSig(v){if(v==null||!Number.isFinite(Number(v)))return null;const n=Number(v);if(n===0)return 0;const p=Math.pow(10,Math.floor(Math.log10(Math.abs(n)))-3);return Number((Math.round(n/p)*p).toPrecision(4))}
// 开单思路（规则版）：方向只看 24h 涨幅与资金费率；点位用现价与日内高低点算，
// 日内高点取 fapi ticker/24hr 的 highPrice（经 marketDetail），取不到就省略该项。
//   资金费率 > 0.5% 或 24h 涨幅 ≥ 200% → 不追多：回踩位 = 日内高点 × 0.85；
//     止损 = 回踩位 × 0.93；目标 = 日内高点 × 1.10。
//   24h 涨幅 ≥ 50%（费率正常）→ 轻仓试多：回踩位 = min(现价, 日内高点 × 0.90)；
//     止损 = 日内低点 × 0.98；目标 = 日内高点 × 1.15。
//   24h 涨幅 ≥ 20%（费率正常）→ 观望：突破位 = 日内高点；
//     止损 = 日内低点 × 0.98；目标 = 日内高点 × 1.20。
//   其余 → 暂无思路（不给点位）。
// 持仓量是单点快照、无变化趋势，只展示不参与方向判断；与第二名差距只影响
// 异动分，不参与开单判断。reason 里带当时的数字，zh/en 各一份。
function briefIdea(c){
const chg=Number(c.change24),fund=c.fundingRate!=null?Number(c.fundingRate):null;
const price=Number(c.price),high=c.highPrice!=null?Number(c.highPrice):null,low=c.lowPrice!=null?Number(c.lowPrice):null;
const okHigh=Number.isFinite(high)&&high>0,okLow=Number.isFinite(low)&&low>0,okPrice=Number.isFinite(price)&&price>0;
const pct1=v=>(v>=0?'+':'')+Number(v).toFixed(1)+'%';
if(!Number.isFinite(chg))return {direction:'none',entry:null,stop:null,target:null,reason:{zh:'数据暂不完整，暂无开单思路。',en:'Data incomplete — no setup.'}};
if((fund!=null&&fund>0.005)||chg>=200){
const entry=okHigh?briefSig(high*0.85):null;
return {direction:'noChase',entry,stop:entry!=null?briefSig(entry*0.93):null,target:okHigh?briefSig(high*1.10):null,reason:fund!=null&&fund>0.005?{zh:'资金费率 '+(fund*100).toFixed(2)+'% 已过热，别追，等回踩。',en:'Funding '+(fund*100).toFixed(2)+'% is overheated — don’t chase; wait for a pullback.'}:{zh:'24h 涨 '+pct1(chg)+'，涨幅过大，追高风险高。',en:'Up '+pct1(chg)+' in 24h — too extended to chase.'}};
}
if(chg>=50){
const entry=okHigh?briefSig(Math.min(okPrice?price:Infinity,high*0.90)):null;
return {direction:'tryLong',entry,stop:okLow?briefSig(low*0.98):null,target:okHigh?briefSig(high*1.15):null,reason:{zh:'放量大涨、费率正常，回踩分批试多。',en:'Strong surge on volume with normal funding — try a light long on pullback.'}};
}
if(chg>=20){
return {direction:'watch',entry:okHigh?briefSig(high):null,stop:okLow?briefSig(low*0.98):null,target:okHigh?briefSig(high*1.20):null,reason:{zh:'涨幅居前但动能一般，等放量突破日内高点。',en:'Leading gains but average momentum — wait for a breakout above the intraday high.'}};
}
return {direction:'none',entry:null,stop:null,target:null,reason:{zh:'涨幅一般，暂无开单思路。',en:'Gains are average — no setup.'}};
}
function briefScore(t,second){
const chg=Math.max(0,Number(t.change24)||0);
const vol=Math.max(0,Number(t.volume)||0);
const round1=v=>Math.round(v*10)/10;
const parts={
change:round1(Math.min(50,chg*0.125)),
volume:round1(Math.max(0,Math.min(20,4*Math.log10(Math.max(1,vol)/10000)))),
funding:t.fundingRate!=null?round1(Math.min(15,Math.abs(Number(t.fundingRate)-0.0001)*1000)):0,
gap:second!=null?round1(Math.min(15,Math.max(0,chg-Number(second.change24||0))*0.05)):0,
};
return {score:Math.round(parts.change+parts.volume+parts.funding+parts.gap),parts};
}
function briefVerdict(t){
if(!t||t.change24==null)return 'quiet';
if(t.fundingRate!=null&&Number(t.fundingRate)>0.005)return 'overheated';
if(Number(t.change24)>=100)return 'strong';
if(Number(t.change24)>=20)return 'watch';
return 'quiet';
}
async function dailyBrief(env){
return cached(env,'daily-brief.json',300000,async()=>{
const m=await markets(env);
const rows=Array.isArray(m.rows)?m.rows:[];
const gainers=rows.filter(r=>r.status==='TRADING'&&Number(r.volume)>=100000&&r.change24!=null).sort((a,c)=>Number(c.change24)-Number(a.change24));
const ranked=gainers.length?gainers:rows.filter(r=>r.change24!=null).sort((a,c)=>Number(c.change24)-Number(a.change24));
const top=ranked[0]||null,second=ranked[1]||null;
// 前 3 名各查一次 marketDetail（日内高低点 + 持仓量，30s 缓存）与
// premiumIndex（资金费率）；任一失败只留空，不让整份异动失败。
const details=await Promise.all(ranked.slice(0,3).map(async r=>{
const [md,fr]=await Promise.allSettled([marketDetail(env,r.symbol),remote(HOST+'premiumIndex?'+new URLSearchParams({symbol:r.symbol}))]);
const d=md.status==='fulfilled'?md.value:null;
const f=fr.status==='fulfilled'&&fr.value&&Number.isFinite(Number(fr.value.lastFundingRate))?Number(fr.value.lastFundingRate):null;
return {symbol:r.symbol,name:r.name,price:r.price,change24:r.change24,volume:r.volume,highPrice:d?d.highPrice:null,lowPrice:d?d.lowPrice:null,openInterest:d?d.openInterest:null,fundingRate:f};
}));
const topOut=details[0]||null;
const {score,parts}=topOut?briefScore(topOut,second):{score:0,parts:{change:0,volume:0,funding:0,gap:0}};
const byName=new Map(rows.map(r=>[r.name,r]));
const dino=BRIEF_DINO.map(n=>byName.get(n)).filter(Boolean).map(r=>({name:r.name,symbol:r.symbol,price:r.price,change24:r.change24,volume:r.volume}));
const todayBjs=new Date(Date.now()+8*3600000).toISOString().slice(0,10);
const events=BRIEF_EVENTS.filter(e=>e.date>=todayBjs);
const ideas=details.map(d=>({symbol:d.symbol,name:d.name,price:d.price,change24:d.change24,volume:d.volume,fundingRate:d.fundingRate,openInterest:d.openInterest,highPrice:d.highPrice,lowPrice:d.lowPrice,idea:briefIdea(d)}));
return {
date:todayBjs,
top:topOut,
top5:ranked.slice(0,5).map(r=>({symbol:r.symbol,name:r.name,price:r.price,change24:r.change24,volume:r.volume})),
secondGap:second&&top?Number(top.change24)-Number(second.change24):null,
newest:rows[0]?{symbol:rows[0].symbol,name:rows[0].name,onboard:rows[0].onboard,change24:rows[0].change24}:null,
score,scoreParts:parts,verdict:briefVerdict(topOut),
dino,events,ideas,
source:'fapi.asterdex.com (markets + ticker/24hr + premiumIndex + openInterest)',
};
});
}
// ===== END DAILY BRIEF =====
async function activities(env){return cached(env,'activities.json',60000,async()=>{const r=await remote('https://www.asterdex.com/bapi/composite/v1/public/composite/ae/announcement/search',{page:1,size:12,category:'ACTIVITY'});if(!Array.isArray(r.data?.rows))throw Error('活动公告格式异常');return {rows:r.data.rows.filter(x=>x.category==='ACTIVITY').map(x=>({id:x.id,title:x.title,subtitle:x.subtitle||'',publishTime:x.publishTime})).sort((a,b)=>b.publishTime-a.publishTime),source:'Aster 官方活动公告',total:r.data.total}})}


export default {async fetch(request,env,ctx){const u=new URL(request.url);try{if(u.pathname==='/api/token-stats')return json(await tokenStats(env));if(u.pathname==='/api/markets')return json(await markets(env));if(u.pathname==='/api/buyback')return json(await buyback(env));if(u.pathname==='/api/activities')return json(await activities(env));if(u.pathname==='/api/announcements')return json(await announcements(env));if(u.pathname==='/api/community')return json(await community(env));if(u.pathname==='/api/daily-brief'){if(env.DAILY_BRIEF_ENABLED===false)return new Response('Not found',{status:404});return json(await dailyBrief(env))}if(u.pathname==='/api/market-detail')return json(await marketDetail(env,u.searchParams.get('symbol')||''));if(u.pathname==='/api/detail')return json(await detail(env,u.searchParams.get('symbol')||''));if(u.pathname==='/api/refresh'&&request.method==='POST'){const results=await Promise.allSettled([markets(env),announcements(env),buyback(env),activities(env),tokenStats(env),community(env),dailyBrief(env)]);return json({results:results.map(x=>x.status==='fulfilled'?{ok:true,updatedAt:x.value.updatedAt,stale:x.value.stale,error:x.value.error}:{ok:false,error:x.reason.message})})}if(u.pathname==='/client.js')return new Response(CLIENT,{headers:{'content-type':'text/javascript; charset=utf-8'}});if(u.pathname==='/assets/aster-logo.svg')return new Response(LOGO,{headers:{'content-type':'image/svg+xml'}});if(u.pathname==='/')return new Response(HTML,{headers:{'content-type':'text/html; charset=utf-8'}});return new Response('Not found',{status:404})}catch(e){return json({error:e.message},502)}}};
